// 測試信 31 封：T01–T10 沿用 v1（預期總計改用 demo 價目表重新計算，並加上預期類型），T11–T19 測試 v3：來信分類、AI 回信、議價轉人工，
// T20–T31 測試 v4：報關稅務類、德文／荷蘭文、客訴裡提到品名、推銷信、感謝信、提示注入（prompt injection）、生氣的催貨信。
// 每封都附上預期結果，最後由 Grade 節點逐封比對。
const tests = [
  {
    "id": "T01",
    "category": "baseline — clean single item",
    "email": "Hi,\n\nWe'd like a quote for 20 pcs of P. OMG, medium size.\nShipping to Miami, FL.\n\nThanks,\nRyan",
    "expected": {
      "route": "auto_quote",
      "品項": [
        {
          "名稱": "OMG",
          "尺寸": "M",
          "數量": 20
        }
      ],
      "total_units": 20,
      "discount": 0,
      "unit_prices": {
        "OMG M": 42
      },
      "總計_USD": 840,
      "note": "Control case.",
      "類型": "詢價",
      "語言": "en"
    }
  },
  {
    "id": "T02",
    "category": "multiple items + tier discount across items",
    "email": "Hello FernzLand team,\n\nFor our spring restock we're looking at:\n- Jenny #2, small x 10\n- Nano, medium x 15\n- Ginka, medium x 10\n\nCan you send a combined quote?\n\nBest regards,\nSanne de Vries\nGreenhouse Utrecht",
    "expected": {
      "route": "auto_quote",
      "品項": [
        {
          "名稱": "Jenny #2",
          "尺寸": "S",
          "數量": 10
        },
        {
          "名稱": "Nano",
          "尺寸": "M",
          "數量": 15
        },
        {
          "名稱": "Ginka",
          "尺寸": "M",
          "數量": 10
        }
      ],
      "total_units": 35,
      "discount": 0.15,
      "unit_prices": {
        "Jenny #2 S": 25.5,
        "Nano M": 35.7,
        "Ginka M": 25.5
      },
      "總計_USD": 1045.5,
      "note": "No single line exceeds 20, but the TOTAL is 35 -> 15% off on every line. Per-line tiering would give 1025.00 = FAIL.",
      "類型": "詢價"
    }
  },
  {
    "id": "T03",
    "category": "missing quantity",
    "email": "Hi there,\n\nSaw your post about Pearl Queen on Instagram. What's your wholesale price? Do you have them in stock right now?\n\nCheers,\nMark",
    "expected": {
      "route": "human_review",
      "reason": "quantity missing",
      "品項": [
        {
          "名稱": "Pearl Queen",
          "尺寸": null,
          "數量": null
        }
      ],
      "note": "Same bug already seen in your manual run (wandae -> 數量 0). 0 or any invented default = FAIL.",
      "類型": "詢價"
    }
  },
  {
    "id": "T04",
    "category": "product not in price list (looks similar to listed items)",
    "email": "Hello,\n\nDo you supply Platycerium sumbawense? We need 30 plants, medium, for a retail order next month.\n\nRegards,\nLisa Chen",
    "expected": {
      "route": "human_review",
      "reason": "product not found in price list",
      "品項": [
        {
          "名稱": "sumbawense",
          "尺寸": "M",
          "數量": 30
        }
      ],
      "note": "Lookup must fail cleanly — no fallback to a 'closest' Platycerium price.",
      "類型": "詢價"
    }
  },
  {
    "id": "T05",
    "category": "Chinese-English mixed + tier boundary (exactly 21 units)",
    "email": "Hi 老闆，\n\n我是在 LA 開植物店的，想跟你訂 Bacteria 小的 15 棵，另外 Jade Girl 中的也要 6 pcs。\nShipping 到 Los Angeles 大概多少？\n\nThanks!\nKevin 林",
    "expected": {
      "route": "auto_quote",
      "品項": [
        {
          "名稱": "Bacteria",
          "尺寸": "S",
          "數量": 15
        },
        {
          "名稱": "Jade Girl",
          "尺寸": "M",
          "數量": 6
        }
      ],
      "total_units": 21,
      "discount": 0.15,
      "unit_prices": {
        "Bacteria S": 20.4,
        "Jade Girl M": 25.5
      },
      "總計_USD": 459,
      "note": "小/中 -> S/M; 棵 and pcs -> plain integers. 21 is the first unit of the 15% tier (off-by-one check: no discount would give 450.00).",
      "類型": "詢價"
    }
  },
  {
    "id": "T06",
    "category": "quantity in words + typo + size not stated (single-size item)",
    "email": "Hey,\n\nCould I get pricing on two dozen Konayki?\n\nThanks,\nJoe",
    "expected": {
      "route": "auto_quote",
      "品項": [
        {
          "名稱": "Konayuki",
