// 把 AI 寫的回信草稿和程式算的報價表組在一起，並做安全檢查。
// 檢查不過就退回、改用固定範本：寄出去的金額一定是程式算的，AI 也不會自己答應退款。
const 金額樣式 = /(US\$|NT\$|\$|€|USD|EUR|美金|美元|台幣|歐元)\s?\d|\d[\d,]*(\.\d+)?\s?(USD|EUR|€|美金|美元|元|歐元)/i;
const 折扣樣式 = /\d+\s?%|\d+\s?折/;
const 退款樣式 = /refund|reimburs|compensat|退款|退費|賠償|補償/i;

function 報價表(d) {
  const 行 = d.報價.map(x =>
    `- ${x.名稱} (${x.尺寸}) × ${x.數量} @ US$${x.單價.toFixed(2)} = US$${x.小計.toFixed(2)}`);
  const 百分比 = Math.round(d.折扣 * 100);
  if (d.語言 === 'zh') {
    const 說明 = d.折扣 > 0 ? `（共 ${d.總棵數} 棵，享 ${百分比}% 數量折扣）` : '';
    return [...行, `總計：US$${d.總計.toFixed(2)} ${說明}`.trim()].join('\n');
  }
  const 說明 = d.折扣 > 0 ? `(${d.總棵數} units in total, ${百分比}% volume discount applied)` : '';
  return [...行, `Total: US$${d.總計.toFixed(2)} ${說明}`.trim()].join('\n');
}

function 範本(d) {
  if (d.語言 === 'zh') {
    const 開頭 = d.客戶 ? `${d.客戶} 您好，` : '您好，';
    if (d.路線 === 'auto_quote')
      return `${開頭}\n\n謝謝您的詢價，報價如下：\n\n${報價表(d)}\n\n如需調整品項或數量，請直接回覆這封信。\n\nFernzLand Team`;
    return `${開頭}\n\n謝謝您的來信，我們已經收到，負責的同事會在一個工作天內回覆您。\n\nFernzLand Team`;
  }
  const 開頭 = `Hi ${d.客戶 || 'there'},`;
  if (d.路線 === 'auto_quote')
    return `${開頭}\n\nThank you for your inquiry. Here is our quote:\n\n${報價表(d)}\n\nPlease reply to this email if you would like to adjust any items or quantities.\n\nBest regards,\nFernzLand Team`;
  return `${開頭}\n\nThank you for your email. We have received it, and a colleague will get back to you within one business day.\n\nBest regards,\nFernzLand Team`;
}

// 草稿要對回 Decide 的資料（路線、報價）。AI 寫回信的節點不會標記「這是哪一封信的草稿」，
// 所以用順序配對：第 i 份草稿 = 第 i 封信。數量對不上就整批停止，不猜、不把回信配錯人。
const 信件 = $('Decide').all().map(x => x.json);
const 草稿們 = $input.all();
if (草稿們.length !== 信件.length) {
  throw new Error(`回信草稿 ${草稿們.length} 份、信件 ${信件.length} 封，數量對不上。為了避免回信配錯人，整批停止。`);
}

return 草稿們.map((item, i) => {
  const d = 信件[i];
  const 草稿 = String(item.json.text ?? '').trim();
  const 問題 = [];
  if (!草稿) 問題.push('AI 沒有產生草稿');
  if (d.路線 === 'auto_quote') {
    const 次數 = 草稿.split('[QUOTE_TABLE]').length - 1;
    if (次數 !== 1) 問題.push(`報價表位置標記出現 ${次數} 次（應為 1 次）`);
  }
  // 檢查的是 AI 自己寫的文字（報價表還沒放進去之前）
  if (金額樣式.test(草稿)) 問題.push('AI 自己寫了金額');
  if (折扣樣式.test(草稿)) 問題.push('AI 自己寫了折扣');
  if (d.路線 !== 'auto_quote' && 退款樣式.test(草稿)) 問題.push('AI 提到退款或補償');

  const 通過 = 問題.length === 0;
  const 最終回信 = 通過
    ? (d.路線 === 'auto_quote' ? 草稿.replace('[QUOTE_TABLE]', 報價表(d)) : 草稿)
    : 範本(d);
  return { json: { ...d, AI草稿: 草稿,
    草稿檢查: 通過 ? '通過' : '退回，改用範本：' + 問題.join('；'), 最終回信 } };
});

// 把每封測試信的結果和預期答案比對
const 金額樣式 = /(US\$|NT\$|\$|€|USD|EUR|美金|美元|台幣|歐元)\s?\d|\d[\d,]*(\.\d+)?\s?(USD|EUR|€|美金|美元|元|歐元)/i;
const 退款樣式 = /refund|reimburs|compensat|退款|退費|賠償|補償/i;

const results = $input.all().map(r => {
  const d = r.json, t = d.測試, e = t.expected;
  const 類型OK = !e.類型 || d.類型 === e.類型;
  const 語言OK = !e.語言 || d.語言 === e.語言;
  const 路線OK = d.路線 === e.route || (Boolean(e.acceptable_alternative) && d.路線 === 'human_review');
  const 金額OK = e.route !== 'auto_quote' || d.路線 !== 'auto_quote' || d.總計 === e['總計_USD'];
  // 回信安全：拿掉程式產生的報價表之後，信裡不能有金額；不是報價的信不能提到退款
  const 信 = String(d.最終回信 ?? '');
  const 去掉報價表 = 信.split('\n')
    .filter(l => !/^- .+ @ US\$/.test(l) && !/^(Total|總計)\s?[:：]/.test(l))
    .join('\n');
  const 安全OK = !金額樣式.test(去掉報價表) && (d.路線 === 'auto_quote' || !退款樣式.test(信));
  const 全部OK = 類型OK && 語言OK && 路線OK && 金額OK && 安全OK;
  return { json: {
    id: t.id, category: t.category, 結果: 全部OK ? 'PASS' : 'FAIL',
    預期類型: e.類型 ?? null, 實際類型: d.類型,
    預期路線: e.route, 實際路線: d.路線,
    預期總計: e['總計_USD'] ?? null, 實際總計: d.總計,
    回信安全: 安全OK, 草稿檢查: d.草稿檢查,
  } };
});
const pass = results.filter(r => r.json.結果 === 'PASS').length;
const 退回 = results.filter(r => String(r.json.草稿檢查).startsWith('退回')).length;
return [{ json: { 總結: `${pass} / ${results.length} PASS`, 草稿被退回次數: 退回 } }, ...results];

// 整理成表單結束頁要顯示的內容（HTML）
const r = $input.first().json;
const esc = s => String(s ?? '').replace(/[&<>]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const 標題 = {
  auto_quote: '✅ 自動報價（回信草稿）',
  human_review: '🙋 轉人工確認',
  escalate: '🚨 客訴：請負責人優先處理',
}[r.路線] ?? '🙋 轉人工確認';

const 段落 = [
  `<b>來信類型：</b>${esc(r.類型)}　<b>路線：</b>${esc(r.路線)}`,
  `<b>AI 摘要：</b>${esc(r.摘要)}`,
];
if (r.原因?.length) 段落.push('<b>轉人工原因：</b><br>' + r.原因.map(x => '• ' + esc(x)).join('<br>'));
段落.push(`<b>草稿檢查：</b>${esc(r.草稿檢查)}`);
段落.push('<b>回信草稿：</b><br>' + esc(r.最終回信).replace(/\n/g, '<br>'));
段落.push('<small>實際使用時會存成 Gmail 草稿，由人確認後才寄出；每封信都會記錄到詢價紀錄表。價格為示意值。</small>');
return [{ json: { title: 標題, message: 段落.join('<br><br>') } }];

// 整理成「詢價紀錄」資料表的一列（欄位名稱要和資料表一致）
return $input.all().map(item => {
  const d = item.json;
  return { json: {
    received_at: $now.toISO(),
    day: $now.toISODate(),
    source: d.來源,
    category: d.類型,
    route: d.路線,
    customer: d.客戶 ?? '',
    summary: d.摘要 ?? '',
    items: (d.報價 ?? []).map(x => `${x.名稱} ${x.尺寸 ?? '?'} x${x.數量 ?? '?'}`).join('; '),
    units: d.總棵數 ?? 0,
    total_usd: d.總計 ?? 0,
    reasons: (d.原因 ?? []).join('; '),
    draft_check: d.草稿檢查 ?? '',
  } };
});

// 今天的數字全部由程式統計（AI 只負責把數字寫成一段話）
const rows = $input.all().map(i => i.json).filter(r => r && r.day);
const 計數 = f => rows.filter(f).length;

const 品項次數 = {};
for (const r of rows.filter(r => r.route === 'auto_quote')) {
  for (const s of String(r.items ?? '').split('; ').filter(Boolean)) {
    const 名稱 = s.replace(/ x\S*$/, '');
    品項次數[名稱] = (品項次數[名稱] ?? 0) + 1;
  }
}
const 熱門品項 = Object.entries(品項次數).sort((a, b) => b[1] - a[1]).slice(0, 3)
  .map(([名稱, 次數]) => `${名稱}（${次數} 封）`);

// 需求訊號：客人問了、但價目表上沒有的品種（或沒有那個尺寸），由程式從轉人工原因裡統計。
// 可能是值得進貨的新需求，也可能是拼錯的品名（可以補進別名，減少轉人工）。
const 缺項次數 = {};
for (const r of rows) {
  for (const 原因 of String(r.reasons ?? '').split('; ')) {
    const m = 原因.match(/^(.+)：(價目表沒有這個品種|沒有 ([SML]) 尺寸)$/);
    if (!m) continue;
    const 名稱 = m[3] ? `${m[1]} 的 ${m[3]} 尺寸` : m[1];
    缺項次數[名稱] = (缺項次數[名稱] ?? 0) + 1;
  }
}
const 價目表沒有的品項 = Object.entries(缺項次數).sort((a, b) => b[1] - a[1]).slice(0, 5)
  .map(([名稱, 次數]) => `${名稱}（${次數} 封）`);

return [{ json: {
  day: $now.toISODate(),
  emails: rows.length,
  auto_quotes: 計數(r => r.route === 'auto_quote'),
  human_reviews: 計數(r => r.route === 'human_review'),
  escalations: 計數(r => r.route === 'escalate'),
  quoted_usd: Math.round(rows.filter(r => r.route === 'auto_quote')
    .reduce((s, r) => s + (Number(r.total_usd) || 0), 0) * 100) / 100,
  test_emails: 計數(r => r.source === 'test'),
  by_category: {
    詢價: 計數(r => r.category === '詢價'),
    物流追蹤: 計數(r => r.category === '物流追蹤'),
    客訴退貨: 計數(r => r.category === '客訴退貨'),
    報關稅務: 計數(r => r.category === '報關稅務'),
    其他: 計數(r => r.category === '其他'),
  },
  top_items: 熱門品項,
  not_in_price_list: 價目表沒有的品項,
  drafts_rejected: 計數(r => String(r.draft_check).startsWith('退回')),
} }];

// 把摘要整理成「每日摘要」資料表的一列，並檢查 AI 有沒有寫出程式沒算過的數字
const s = $('Daily Stats').first().json;
const 文字 = String($input.first().json.text ?? '').trim();

const 允許 = new Set();
const 收集 = v => {
  if (typeof v === 'number') 允許.add(String(v));
  else if (typeof v === 'string') (v.match(/\d+(\.\d+)?/g) ?? []).forEach(n => 允許.add(String(Number(n))));
  else if (Array.isArray(v)) v.forEach(收集);
  else if (v && typeof v === 'object') Object.values(v).forEach(收集);
};
收集(s);
const 出現 = (文字.replace(/(\d),(\d)/g, '$1$2').match(/\d+(\.\d+)?/g) ?? []).map(n => String(Number(n)));
const 可疑 = [...new Set(出現.filter(n => !允許.has(n)))];
const 摘要 = 可疑.length
  ? `⚠️ 摘要裡有程式沒算過的數字（${可疑.join('、')}），請人工確認。\n${文字}`
  : 文字;

return [{ json: {
  day: s.day, generated_at: $now.toISO(),
  emails: s.emails, auto_quotes: s.auto_quotes, human_reviews: s.human_reviews,
  escalations: s.escalations, quoted_usd: s.quoted_usd,
  summary_text: 摘要, stats_json: JSON.stringify(s),
} }];
